--
-- Table structure for table `biz_merchant_archive`
--

DROP TABLE IF EXISTS `biz_merchant_archive`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `biz_merchant_archive` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `enterprise_id` bigint DEFAULT NULL COMMENT '所属企业租户',
  `code` varchar(100) DEFAULT NULL COMMENT '商户编码',
  `name` varchar(100) DEFAULT NULL COMMENT '商户名称',
  `category_id` bigint DEFAULT NULL COMMENT '商户分类ID',
  `location` varchar(20) DEFAULT NULL COMMENT '所在地区',
  `address` varchar(100) DEFAULT NULL COMMENT '地址',
  `contact` varchar(100) DEFAULT NULL COMMENT '上下游联系人',
  `phone` varchar(20) DEFAULT NULL COMMENT '上下游联系手机',
  `bank` varchar(100) DEFAULT NULL COMMENT '商户开户行',
  `bank_card_num` varchar(100) DEFAULT NULL COMMENT '商户银行卡号',
  `channel` varchar(100) DEFAULT NULL COMMENT '渠道',
  `service_phone` varchar(20) DEFAULT NULL COMMENT '商户公共服务电话',
  `default_area_code` varchar(20) DEFAULT NULL COMMENT '默认区域',
  `created_at` datetime DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime DEFAULT NULL COMMENT '更新时间',
  `updated_by` bigint DEFAULT NULL COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '软删除',
  `direction` varchar(32) DEFAULT NULL COMMENT '上下游方向',
  `active_name` varchar(100) GENERATED ALWAYS AS ((case when (`deleted` = 0) then trim(`name`) else NULL end)) STORED,
  PRIMARY KEY (`id`),
  KEY `idx_biz_merchant_archive_category` (`enterprise_id`,`category_id`,`deleted`)
) ENGINE=InnoDB AUTO_INCREMENT=2090661322625305502 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='业务商户表';
/*!40101 SET character_set_client = @saved_cs_client */;

