--
-- Table structure for table `saas_order_archive`
--

DROP TABLE IF EXISTS `saas_order_archive`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `saas_order_archive` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `order_no` varchar(64) DEFAULT NULL COMMENT '订单号',
  `order_type` varchar(32) DEFAULT NULL COMMENT 'BUY RENEW AUTO_RENEW CHANGE_PLAN',
  `enterprise_id` bigint DEFAULT NULL COMMENT '企业ID',
  `buyer_user_id` bigint DEFAULT NULL COMMENT '购买人',
  `plan_id` bigint DEFAULT NULL COMMENT '套餐ID',
  `plan_snapshot_json` json DEFAULT NULL COMMENT '下单时套餐快照',
  `buy_user_limit` int DEFAULT NULL COMMENT '购买人数',
  `buy_workorder_limit` int DEFAULT NULL COMMENT '下单时套餐工单额度',
  `buy_duration_days` int DEFAULT NULL COMMENT '购买时长',
  `workorder_overage_count` int NOT NULL DEFAULT '0' COMMENT '套餐变更时立即计费的超额工单数',
  `workorder_overage_amount` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '套餐变更时立即计收的超额工单费用',
  `pay_type` varchar(32) DEFAULT NULL COMMENT 'BALANCE ONLINE',
  `amount` decimal(12,2) DEFAULT NULL COMMENT '应付金额',
  `price_amount` decimal(12,2) DEFAULT NULL COMMENT 'original price amount',
  `discount_amount` decimal(12,2) DEFAULT NULL COMMENT 'discount amount',
  `credit_amount` decimal(12,2) DEFAULT NULL COMMENT 'remaining value credit',
  `payable_amount` decimal(12,2) DEFAULT NULL COMMENT 'final payable amount',
  `refund_amount` decimal(12,2) DEFAULT NULL COMMENT 'refund to wallet amount',
  `paid_amount` decimal(12,2) DEFAULT NULL COMMENT '实付金额',
  `pay_channel` varchar(32) DEFAULT NULL COMMENT '支付渠道',
  `pay_trade_no` varchar(100) DEFAULT NULL COMMENT '第三方交易号',
  `wallet_transaction_id` bigint DEFAULT NULL COMMENT 'wallet transaction id',
  `original_subscription_id` bigint DEFAULT NULL COMMENT 'original subscription id',
  `old_plan_id` bigint DEFAULT NULL COMMENT 'old plan id',
  `new_plan_id` bigint DEFAULT NULL COMMENT 'new plan id',
  `auto_renew` tinyint NOT NULL DEFAULT '0' COMMENT 'auto renew order flag',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '1待支付 2已支付 3已取消 4已退款 5已关闭 6自动续费失败',
  `failure_reason` varchar(500) DEFAULT NULL COMMENT '自动续费失败原因',
  `paid_at` datetime DEFAULT NULL COMMENT '支付时间',
  `created_at` datetime DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '软删除',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='SaaS套餐订单表';
/*!40101 SET character_set_client = @saved_cs_client */;

