DROP TABLE IF EXISTS `saas_recharge_order_archive`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `saas_recharge_order_archive` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `recharge_no` varchar(64) DEFAULT NULL COMMENT 'recharge order no',
  `enterprise_id` bigint DEFAULT NULL COMMENT 'enterprise id',
  `user_id` bigint DEFAULT NULL COMMENT 'operator user id',
  `amount` decimal(12,2) DEFAULT NULL COMMENT 'recharge amount',
  `pay_channel` varchar(32) DEFAULT NULL COMMENT 'pay channel',
  `pay_trade_no` varchar(100) DEFAULT NULL COMMENT 'third-party trade no',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '1 pending 2 paid 3 canceled 4 failed',
  `paid_at` datetime DEFAULT NULL COMMENT 'paid time',
  `created_at` datetime DEFAULT NULL COMMENT 'created time',
  `updated_at` datetime DEFAULT NULL COMMENT 'updated time',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT 'soft delete',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='SaaS recharge order archive';
