DROP TABLE IF EXISTS `saas_visitor_lead`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `saas_visitor_lead` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `lead_no` varchar(32) NOT NULL COMMENT '对外游客编号，格式为VL+日期+随机字符',
  `name` varchar(100) NOT NULL COMMENT '游客姓名',
  `contact` varchar(100) NOT NULL COMMENT '手机号、微信号或邮箱等联系方式',
  `role_code` varchar(32) DEFAULT NULL COMMENT 'OPC_AGENT CAR_DEALER INSURANCE_AGENCY OTHER',
  `expected_monthly_orders` int unsigned DEFAULT NULL COMMENT '预计月单量，非负整数',
  `intent_codes` json DEFAULT NULL COMMENT '合作诉求编码数组：TRIAL DEMO CUSTOM_COOPERATION',
  `remark` varchar(1000) DEFAULT NULL COMMENT '游客备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '提交时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最后更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '0正常 1软删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_saas_visitor_lead_no` (`lead_no`),
  KEY `idx_saas_visitor_lead_created` (`deleted`,`created_at`,`id`),
  CONSTRAINT `chk_saas_visitor_lead_intent_codes` CHECK (((json_type(`intent_codes`) = _utf8mb4'ARRAY') and (json_length(`intent_codes`) between 1 and 3) and (json_contains(json_array(_utf8mb4'TRIAL',_utf8mb4'DEMO',_utf8mb4'CUSTOM_COOPERATION'),`intent_codes`) = 1))),
  CONSTRAINT `chk_saas_visitor_lead_monthly_orders` CHECK ((`expected_monthly_orders` >= 0)),
  CONSTRAINT `chk_saas_visitor_lead_role` CHECK ((`role_code` in (_utf8mb4'OPC_AGENT',_utf8mb4'CAR_DEALER',_utf8mb4'INSURANCE_AGENCY',_utf8mb4'OTHER')))
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='SaaS门户官网游客线索';
